SET @mw_ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='document_indexes' AND column_name='knowledge_base_id')=0, 'ALTER TABLE document_indexes ADD COLUMN knowledge_base_id varchar(32) CHARACTER SET ascii COLLATE ascii_bin NULL', 'DO 0');
PREPARE mw_statement FROM @mw_ddl;
EXECUTE mw_statement;
DEALLOCATE PREPARE mw_statement;
