UPDATE document_indexes i JOIN documents d ON d.id=i.document_id SET i.knowledge_base_id=d.knowledge_base_id WHERE i.knowledge_base_id IS NULL;
UPDATE chunks c JOIN document_indexes i ON i.id=c.index_id SET c.workspace_id=COALESCE(c.workspace_id,i.workspace_id),c.knowledge_base_id=COALESCE(c.knowledge_base_id,i.knowledge_base_id) WHERE c.workspace_id IS NULL OR c.knowledge_base_id IS NULL;
